import React from 'react';
import './SummaryStep.css';

const SummaryStep = ({ character, calculateModifier }) => {
    return (
        <div className="summary-container fade-in">
            {/* ÜST BÖLÜM: Portre ve Temel Bilgiler */}
            <div className="summary-header-card">
                <div className="summary-portrait">
                    {character.portrait ? (
                        <img src={character.portrait} alt="Portrait" />
                    ) : (
                        <div className="no-portrait-placeholder">NO IMAGE</div>
                    )}
                </div>
                <div className="summary-main-info">
                    <h1 className="summary-char-name">{character.name || "Unnamed Hero"}</h1>
                    <p className="summary-char-subtitle">
                        Level {character.level} {character.species} {character.charClass}
                    </p>
                    <div className="summary-combat-ribbon">
                        <div className="ribbon-item"><span>AC</span><strong>{character.armorClass}</strong></div>
                        <div className="ribbon-item"><span>HP</span><strong>{character.currentHp}/{character.maxHp}</strong></div>
                        <div className="ribbon-item"><span>INIT</span><strong>{calculateModifier(character.stats.Dexterity) >= 0 ? '+' : ''}{calculateModifier(character.stats.Dexterity)}</strong></div>
                        <div className="ribbon-item"><span>SPD</span><strong>{character.speed}ft</strong></div>
                    </div>
                </div>
            </div>

            <div className="summary-grid">
                {/* SOL KOLON: Statlar ve Skiller */}
                <div className="summary-column">
                    <div className="summary-section stats-mini-grid">
                        {Object.entries(character.stats).map(([stat, value]) => (
                            <div className="stat-pill" key={stat}>
                                <label>{stat.substring(0, 3)}</label>
                                <strong>{value}</strong>
                                <span>({calculateModifier(value) >= 0 ? '+' : ''}{calculateModifier(value)})</span>
                            </div>
                        ))}
                    </div>

                    <div className="summary-section">
                        <h3 className="summary-title">Proficiencies</h3>
                        <div className="prof-tags">
                            {/* Sadece seçili olan yetkinlikleri gösteriyoruz */}
                            {Object.keys(character.proficiencies).filter(k => character.proficiencies[k]).map(key => (
                                <span className="prof-tag" key={key}>{key.split('-')[1]}</span>
                            ))}
                        </div>
                    </div>
                </div>

                {/* SAĞ KOLON: Ekipman ve Özellikler */}
                <div className="summary-column">
                    <div className="summary-section">
                        <h3 className="summary-title">Top Weapons</h3>
                        {character.weapons.slice(0, 3).map(w => (
                            <div className="weapon-mini-row" key={w.id}>
                                <strong>{w.name}</strong>
                                <span>{w.damageDice}</span>
                            </div>
                        ))}
                    </div>

                    <div className="summary-section">
                        <h3 className="summary-title">Character Traits</h3>
                        <p className="summary-text-block"><em>"{character.traits.personality}"</em></p>
                    </div>
                </div>
            </div>

            {/* ALT BÖLÜM: Biyografi Özeti */}
            <div className="summary-footer-section">
                <h3 className="summary-title">Backstory Snapshot</h3>
                <p className="summary-backstory-preview">
                    {character.backstory ? character.backstory.substring(0, 300) + "..." : "No backstory recorded."}
                </p>
            </div>
        </div>
    );
};

export default SummaryStep;
